-- The schema of the database before the migration framework existed (commit d320b69), as created by that version's db.ts.
CREATE TRIGGER memories_ad AFTER DELETE ON memories BEGIN
  INSERT INTO memories_fts(memories_fts, rowid, text, tags) VALUES ('delete', old.id, old.text, old.tags);
END;
CREATE TRIGGER memories_ai AFTER INSERT ON memories BEGIN
  INSERT INTO memories_fts(rowid, text, tags) VALUES (new.id, new.text, new.tags);
END;
CREATE TABLE catalog (id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, builtin INTEGER NOT NULL DEFAULT 0, spec TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'available', x REAL, z REAL, ids TEXT NOT NULL DEFAULT '[]', ts INTEGER NOT NULL);
CREATE TABLE compositions (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL UNIQUE COLLATE NOCASE, spec TEXT NOT NULL, ts INTEGER NOT NULL, plays INTEGER NOT NULL DEFAULT 0);
CREATE TABLE creatures (id TEXT PRIMARY KEY, species TEXT NOT NULL, trait TEXT NOT NULL, name TEXT, trust REAL NOT NULL DEFAULT 0, met INTEGER NOT NULL DEFAULT 0, last_seen INTEGER NOT NULL DEFAULT 0, alive INTEGER NOT NULL DEFAULT 1);
CREATE TABLE desires (
  id INTEGER PRIMARY KEY AUTOINCREMENT, text TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 5,
  status TEXT NOT NULL DEFAULT 'active', created INTEGER NOT NULL, outcome TEXT
);
CREATE TABLE entities (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, x REAL, z REAL, props TEXT NOT NULL);
CREATE TABLE events (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL, text TEXT NOT NULL, data TEXT
);
CREATE TABLE forged (
  name TEXT PRIMARY KEY, request_id INTEGER, status TEXT NOT NULL, code TEXT NOT NULL DEFAULT '', log TEXT NOT NULL DEFAULT '', ts INTEGER NOT NULL
);
CREATE TABLE interests (topic TEXT PRIMARY KEY, weight REAL NOT NULL, why TEXT NOT NULL DEFAULT '', updated INTEGER NOT NULL);
CREATE TABLE inventory (id TEXT PRIMARY KEY, kind TEXT, name TEXT, desc TEXT, qty INTEGER, props TEXT);
CREATE TABLE journal (day INTEGER PRIMARY KEY, text TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE kv (k TEXT PRIMARY KEY, v TEXT NOT NULL);
CREATE TABLE lives (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, born INTEGER NOT NULL, died INTEGER NOT NULL, days REAL NOT NULL, cause TEXT NOT NULL, x REAL, z REAL, summary TEXT NOT NULL DEFAULT '');
CREATE TABLE memories (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL,
  text TEXT NOT NULL, importance REAL NOT NULL, tags TEXT NOT NULL DEFAULT '',
  last_access INTEGER, access_count INTEGER NOT NULL DEFAULT 0
, embedding BLOB, x REAL, z REAL);
CREATE VIRTUAL TABLE memories_fts USING fts5(text, tags, content='memories', content_rowid='id');
CREATE TABLE moments (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, kind TEXT NOT NULL, title TEXT NOT NULL, text TEXT NOT NULL, intensity REAL NOT NULL, emotions TEXT NOT NULL, x REAL, z REAL);
CREATE TABLE opinions (id INTEGER PRIMARY KEY AUTOINCREMENT, subject TEXT NOT NULL UNIQUE COLLATE NOCASE, stance TEXT NOT NULL, why TEXT NOT NULL DEFAULT '', ts INTEGER NOT NULL, strength INTEGER NOT NULL DEFAULT 1);
CREATE TABLE palette (name TEXT PRIMARY KEY COLLATE NOCASE, hex TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE places (
  id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, x REAL NOT NULL, z REAL NOT NULL, note TEXT NOT NULL DEFAULT '', ts INTEGER NOT NULL
);
CREATE TABLE tool_requests (
  id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, name TEXT NOT NULL, reason TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'pending', custom INTEGER NOT NULL DEFAULT 0, note TEXT
, matches TEXT, match_score REAL);
CREATE TABLE tools (name TEXT PRIMARY KEY, approved INTEGER NOT NULL DEFAULT 0);
CREATE TABLE tunes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE COLLATE NOCASE, notes TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE TABLE works (id INTEGER PRIMARY KEY AUTOINCREMENT, ts INTEGER NOT NULL, name TEXT NOT NULL, shape TEXT NOT NULL, size TEXT NOT NULL, materials TEXT NOT NULL, colors TEXT NOT NULL, color_names TEXT NOT NULL, x REAL, z REAL, entity TEXT);
